// Diagnostic sampling only. The native helper reads GO from stdin, then runs
// its measured phase and final fsync. No prefill, warmup or readback samples.
config = { max_map_keys=16384; perf_rb_pages=256; }
BEGIN { printf("PROFILE_READY\n"); }
tracepoint:syscalls:sys_enter_read
/comm == "io-replay-nativ" && uid == 0 && args.fd == 0/
{ @reading[tid] = 1; }
tracepoint:syscalls:sys_exit_read
/@reading[tid]/
{
  delete(@reading[tid]);
  if (args.ret == 3) {
    if (@active) { @overlaps++; }
    @sequence++;
    @active = pid;
    @go[@sequence] = nsecs;
    printf("GO %llu %d %llu\n", @sequence, pid, nsecs);
  }
}
tracepoint:syscalls:sys_exit_fsync
/pid == @active/
{
  @end[@sequence] = nsecs;
  @active = 0;
  printf("END %llu %d %llu %d\n", @sequence, pid, nsecs, args.ret);
}
hardware:cycles:500000
/@active/
{
  @counts[@sequence] = count();
  printf("SAMPLE %llu %d %d %s %s\n", @sequence, cpu, tid, comm, kstack(raw, 40));
}

// Identify work functions while their module is loaded. Only one name event
// per function per measured gate; no per-page production function probes.
tracepoint:workqueue:workqueue_execute_start
{
  @function[tid] = (uint64)args.function;
  @work_start[tid] = nsecs;
  if (@active) { @on_start[tid] = nsecs; @scope[tid] = @sequence; }
}
tracepoint:sched:sched_switch
{
  $task = args.prev_pid;

  $function = @function[$task];
  if ($function && (@active || @scope[$task])) {
    $seq = @scope[$task];
    if (!$seq) { $seq = @sequence; }
    $start = @on_start[$task];
    if (!$start) {
      $start = @work_start[$task];
      if ($start < @go[$seq]) { $start = @go[$seq]; }
    }
    $stop = nsecs;
    if (@end[$seq] && $stop > @end[$seq]) { $stop = @end[$seq]; }
    if ($stop > $start) { @work_oncpu_ns[$seq, $function] = sum($stop - $start); }
    if (!@named[$seq, $function]) {
      @named[$seq, $function] = 1;
      printf("FUNCTION %llu %llu %s\n", $seq, $function, ksym($function));
    }
    delete(@on_start[$task]); delete(@scope[$task]);
  }

  if (@function[args.next_pid] && @active) {
    @on_start[args.next_pid] = nsecs; @scope[args.next_pid] = @sequence;
  }
}
tracepoint:workqueue:workqueue_execute_end
{
  $task = tid;

  $function = @function[$task];
  if ($function && (@active || @scope[$task])) {
    $seq = @scope[$task];
    if (!$seq) { $seq = @sequence; }
    $start = @on_start[$task];
    if (!$start) {
      $start = @work_start[$task];
      if ($start < @go[$seq]) { $start = @go[$seq]; }
    }
    $stop = nsecs;
    if (@end[$seq] && $stop > @end[$seq]) { $stop = @end[$seq]; }
    if ($stop > $start) { @work_oncpu_ns[$seq, $function] = sum($stop - $start); }
    if (!@named[$seq, $function]) {
      @named[$seq, $function] = 1;
      printf("FUNCTION %llu %llu %s\n", $seq, $function, ksym($function));
    }
    delete(@on_start[$task]); delete(@scope[$task]);
  }

  delete(@function[tid]); delete(@work_start[tid]);
  delete(@on_start[tid]); delete(@scope[tid]);
}
END {
  printf("PROFILE_STOP active=%d overlaps=%d\n", @active, @overlaps);
  clear(@reading); clear(@function); clear(@work_start);
  clear(@on_start); clear(@scope); clear(@named); clear(@go); clear(@end);
}

resolver_script:
import bisect,collections,hashlib,json,math,re,statistics,subprocess
from pathlib import Path
p=Path(__file__).parent
module=Path('build/kernel/experimental/dm-swapz.ko')
sections={}
for line in subprocess.check_output(['readelf','-SW',str(module)],text=True).splitlines():
 m=re.match(r'\s*\[\s*(\d+)\]\s+(\S+)\s+\S+\s+([0-9a-f]+)\s+([0-9a-f]+)\s+([0-9a-f]+)',line)
 if m:sections[m[1]]=(m[2],int(m[5],16))
funcs=[]
for line in subprocess.check_output(['readelf','-sW',str(module)],text=True).splitlines():
 v=line.split()
 if len(v)>=8 and v[3]=='FUNC' and v[6] in sections and int(v[2]):
  funcs.append((v[6],int(v[1],16),int(v[2]),v[7]))
kern=[]
for line in (p/'kernel-kallsyms.txt').read_text().splitlines():
 v=line.split()
 if len(v)>=3 and v[1] in 'tTwW' and int(v[0],16):kern.append((int(v[0],16),v[2]))
kern.sort();kaddrs=[v[0] for v in kern]
snapshots=json.loads((p/'module-sections.json').read_text())
lines=(p/'raw-stacks.log').read_text().splitlines();gates={}; samples=collections.defaultdict(list); counts={};cpu=collections.defaultdict(dict)
for line in lines:
 if line.startswith('GO '):
  _,seq,pid,stamp=line.split();gates[int(seq)]={'start_ns':int(stamp),'pid':int(pid)}
 if line.startswith('END '):
  _,seq,pid,stamp,rc=line.split();gates[int(seq)].update(end_ns=int(stamp),rc=int(rc))
 m=re.match(r'@counts\[(\d+)\]: (\d+)',line)
 if m:counts[int(m[1])]=int(m[2])
 m=re.match(r'@work_oncpu_ns\[(\d+), (\d+)\]: (\d+)',line)
 if m:cpu[int(m[1])][int(m[2])]=int(m[3])
current=None
for line in lines:
 if line.startswith('SAMPLE '):
  v=line.split();current=(int(v[1]),[]);samples[current[0]].append(current[1])
 elif current and re.fullmatch(r'[0-9a-f]{16}',line.strip()):current[1].append(int(line.strip(),16))
 elif line and not line.startswith(' '):current=None
assert set(gates)==set(range(1,7)),gates
assert 'PROFILE_STOP active=0 overlaps=0' in lines
assert all(g['rc']==0 and g['end_ns']>g['start_ns'] for g in gates.values())
assert all(len(samples[seq])==counts.get(seq) for seq in gates)
def resolver(seq):
 snap=max((s for s in snapshots if s['nsecs']<=gates[seq]['start_ns']),key=lambda s:s['nsecs'])
 mapped=[]
 for ndx,off,size,name in funcs:
  section=sections[ndx][0]
  if section in snap['sections']:mapped.append((snap['sections'][section]+off,size,name))
 mapped.sort();starts=[v[0] for v in mapped]
 ranges=[(base,base+size) for name,base in snap['sections'].items() for sec,size in sections.values() if name==sec and name.startswith('.text')]
 def resolve(address):
  i=bisect.bisect_right(starts,address)-1
  if i>=0 and address<mapped[i][0]+mapped[i][1]:return mapped[i][2]
  if any(a<=address<b for a,b in ranges):return 'DM_UNRESOLVED'
  j=bisect.bisect_right(kaddrs,address)-1
  return kern[j][1] if j>=0 and address-kern[j][0]<0x20000 else 'UNRESOLVED'
 return resolve
def category(frames):
 # Mutually exclusive sample labels, deepest relevant frame wins after IRQ.
 if any(re.search(r'(^asm_.*interrupt|^irq_exit|^irq_enter|^__do_softirq|^__sysvec_|^sysvec_)',f) for f in frames):return 'interrupt'
 if frames and 'memset' in frames[0] and any(f.startswith('LZ4_compress_fast') for f in frames):return 'lz4_state_clear'
 for f in frames:
  if re.search(r'(spin_lock|spin_unlock|queued_spin|mutex_|_raw_read_|_raw_write_|rwsem_)',f):return 'lock_or_irq_restore'
  if re.search(r'(crc32|crc32c)',f):return 'crc'
  if 'LZ4_decompress' in f:return 'read_decode'
  if 'LZ4_' in f:
   return 'lz4_compress'
  if re.search(r'swapz_.*(read|decode)',f):return 'read'
  if re.search(r'swapz_.*(publish|authority|commit)',f):return 'publish_or_commit'
  if re.search(r'swapz_.*(plan|fit|sort)',f):return 'plan_or_sort'
  if re.search(r'swapz_.*(pack|append|stage)',f):return 'pack_or_stage'
 return 'other'
x=json.loads((p/'raw-fast-test.json').read_text());output=[]; unresolved=0
for i,obs in enumerate(x['reports']):
 seq=2*(i+1);resolve=resolver(seq);owner=collections.Counter();all_sw=collections.Counter();leaves=collections.Counter();workers={}
 for address,ns in cpu[seq].items():workers[resolve(address)]=ns
 for raw in samples[seq]:
  frames=[resolve(a) for a in raw]
  if any(f=='DM_UNRESOLVED' for f in frames):unresolved+=1
  if any(f.startswith('swapz_') for f in frames):all_sw[category(frames)]+=1
  if 'swapz_worker' in frames:
   owner[category(frames)]+=1
   if frames:leaves[frames[0]]+=1
 arm=obs['arms']['swapz'];output.append({'scenario':obs['scenario'],'gate':seq,'gate_wall_ns':gates[seq]['end_ns']-gates[seq]['start_ns'],'total_samples':len(samples[seq]),'workqueue_irq_inclusive_oncpu_ns':workers,'owner_exclusive_sample_categories':dict(owner),'all_swapz_exclusive_sample_categories':dict(all_sw),'owner_top_leaves':leaves.most_common(12),'write_ops':arm['write_ops'],'read_ops':arm['read_ops'],'performance_validity':x['rows'][i]['performance_validity']})
assert unresolved==0,unresolved
before=json.loads(Path('docs/handoff/serial-budget-x86-diagnostic.json').read_text())
ratio=lambda v:statistics.mean(r['swapz_w']/r['raw_w'] for r in v['rows'])
shift=100*(ratio(x)/ratio(before)-1)
result={'plan':json.loads((p/'corrected-plan.json').read_text()),'symbols':'raw IP resolved from live module section snapshots plus exact module ELF; no unresolved module frames','scope':'IRQ-inclusive scheduled work-function time; not exact uninstrumented CPU. Categories are exclusive hardware-cycle samples, not nanosecond partitions.','instrumented_normalized_write_shift_vs_previous_untraced_pct':shift,'intrusive_by_declared_10pct_rule':abs(shift)>10,'gates':gates,'module_sha256':hashlib.sha256(module.read_bytes()).hexdigest(),'observations':output,'full_reports':x}
(p/'summary.json').write_text(json.dumps(result,indent=2,sort_keys=True)+'\n')
print(json.dumps({'shift_pct':shift,'unresolved_module_frames':unresolved,'observations':output},indent=2))
